from typing import List

class Solution:
    def plusOne(self, digits: List[int]) -> List[int]:
        res = digits[:]
        carry = 1
        for i in range(len(res) - 1, -1, -1):
            total = res[i] + carry
            res[i] = total % 10
            carry = total // 10
            if carry == 0:
                break
        if carry:
            res.insert(0, carry)
        return res

